parameters.jsCode:
const payload = $json.body || {};
const callbackQuery = payload.callback_query || payload;
const data = callbackQuery.data || '';
const parts = data.split(':');

const action = parts[0] || 'unknown'; // 'approve' or 'reject'
const contentId = parts[1] || '';
const versionId = parts[2] || '';

const queryId = callbackQuery.id || '';
const fromUser = callbackQuery.from || {};
const reviewerName = fromUser.username ? `@${fromUser.username}` : (fromUser.first_name || 'Admin');
const reviewerRef = `telegram:${fromUser.id || 'unknown'} (${reviewerName})`;

const message = callbackQuery.message || {};
const messageId = message.message_id || null;
const chatId = message.chat ? message.chat.id : null;
const existingCaption = message.caption || '';

const isApproved = action === 'approve';
const decision = isApproved ? 'approved' : 'changes_requested';
const notes = isApproved ? 'Approved via Telegram Inline Button' : 'Changes requested via Telegram Inline Button';

return [{
  json: {
    is_valid: Boolean(contentId && (action === 'approve' || action === 'reject')),
    action: action,
    decision: decision,
    content_id: contentId,
    version_id: versionId,
    callback_query_id: queryId,
    reviewer_reference: reviewerRef,
    notes: notes,
    message_id: messageId,
    chat_id: chatId,
    existing_caption: existingCaption
  }
}];

